E1.css:
[data-ui-unit="E1"].trip-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 62px;
  gap: 16px;
}

[data-ui-unit="E1"].trip-header > button {
  flex: 0 0 44px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  padding: 0;
  cursor: pointer;
}

[data-ui-unit="E1"].trip-header > button[disabled] {
  opacity: 1;
  cursor: default;
}

[data-ui-unit="E1"].trip-header > button img {
  width: 24px;
  height: 24px;
  display: block;
}

[data-ui-unit="E1"].trip-header > h1 {
  flex: 1;
  margin: 0;
  font-size: 18px;
  line-height: 26px;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

[data-ui-unit="E1"].trip-header > span {
  flex: 0 0 44px;
  width: 44px;
}

E2.css:
[data-ui-unit="E2"].day-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

[data-ui-unit="E2"].day-tabs button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 64px;
  height: 32px;
  padding: 0 12px;
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  border-radius: 16px;
  border: 1px solid var(--border, #e8e8e8);
  background-color: #fff;
  color: var(--ink, #111);
  cursor: pointer;
  white-space: nowrap;
}

[data-ui-unit="E2"].day-tabs button[aria-pressed="true"] {
  background-color: var(--ink, #111);
  color: #fff;
  border-color: transparent;
}

E3.css:
[data-ui-unit="E3"].itinerary {
  color: var(--ink);
}


[data-ui-unit="E3"].itinerary h2 {
  font-size: 16px;
  line-height: 22px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--ink);
}

[data-ui-unit="E3"].itinerary h2 span {
  font-weight: 500;
  color: var(--muted);
}

[data-ui-unit="E3"].itinerary .day-group:not(:last-child) {
  margin-bottom: 40px;
}

[data-ui-unit="E3"].itinerary .place-row:not(:last-child) {
  margin-bottom: 18px;
}


[data-ui-unit="E3"] .place-card {
  background-color: #fff;
  border: 1px solid var(--border);
  border-radius: 6px;
  min-height: 96px;
  display: flex;
  align-items: center;
  overflow: hidden; 
}


[data-ui-unit="E3"] .place-photo {
  width: 96px;
  height: 96px;
  object-fit: cover;
  flex-shrink: 0;
}


[data-ui-unit="E3"] .place-copy {
  min-width: 0;
  flex: 1;
  padding: 8px 12px;
  overflow-wrap: anywhere;
}

[data-ui-unit="E3"] .place-title {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--ink);
  white-space: normal;
}

[data-ui-unit="E3"] .place-region {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 500;
  color: var(--muted);
  margin-bottom: 4px;
  white-space: normal;
}

[data-ui-unit="E3"] .place-type {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 500;
  color: var(--muted);
  white-space: normal;
}


[data-ui-unit="E3"] .place-grip {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  margin-right: 6px;
  object-fit: contain;
}


[data-ui-unit="E3"] .partial-slot {
  margin-left: 31px;
  height: 18px;
  overflow: hidden;
}

[data-ui-unit="E3"] .partial-card {
  min-height: 96px;
  border: 1px solid var(--border);
  border-top-left-radius: 6px;
  border-bottom-left-radius: 6px;
  display: flex;
  align-items: center;
  background-color: #fff;
}

[data-ui-unit="E3"] .partial-card img {
  width: 96px;
  height: auto;
  object-fit: cover;
}


@media (max-width: 360px) {
  [data-ui-unit="E3"] .place-photo {
    width: 72px;
    height: 72px;
  }

  [data-ui-unit="E3"] .place-copy {
    padding: 8px;
  }
}

E4.css:
[data-ui-unit="E4"].trip-footer {
  margin-top: 24px;
}

[data-ui-unit="E4"].trip-footer button[type="button"] {
  display: block;
  width: 100%;
  min-height: 56px;
  padding: 0 16px;
  background-color: #bdbdbd;
  color: #ffffff;
  font-family: "Noto Sans KR", sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 56px;
  text-align: center;
  border-radius: 12px;
  border: none;
  cursor: default;
  opacity: 1;
}

[data-ui-unit="E4"].trip-footer button[type="button"]:disabled {
  background-color: #bdbdbd;
  color: #ffffff;
}
